sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
    },
	isDatePast: function(strDate){
    var now=new GlideDateTime();
	var wn=new GlideDateTime(current.u_when_needed);
	if((wn.getDate().compareTo(now.getDate())===-1)){
		gs.addErrorMessage("When needed time cannot be in past, Your request is not added to the database");
		current.setAbortAction(true);
	}else if(wn.getDate().compareTo(now.getDate())===0){
		gs.addErrorMessage("When needed time cannot today, Your request is not added to the database")
		current.setAbortAction(true);
	}
},
    type: 'NeedItUtils'
};
